// A2UI v0.9 messages, as uia speaks them. An agent describes a *surface*
// (a screen, or a block inside a chat reply) with four kinds of message:
//
//   createSurface     a new surface, and which catalog it uses
//   updateComponents  components, as a flat list keyed by id; children are
//                     referenced by id ("root" is where rendering starts)
//   updateDataModel   the data, set at a JSON Pointer path
//   deleteSurface     remove it
//
// Props are either a literal or a binding into the data model:
// `{ "path": "/spend/total" }`. Actions are named events, never code:
// `{ "event": { "name": "raise_limit", "context": { "limit": 500 } } }`.
// Spec: https://a2ui.org/specification/v0.9-a2ui/

export type DataPath = { path: string }
export type Dynamic<T> = T | DataPath

export type ComponentNode = {
  id: string
  component: string
  [prop: string]: unknown
}

export type CreateSurface = {
  surfaceId: string
  catalogId: string
  theme?: Record<string, unknown>
}
export type UpdateComponents = {
  surfaceId: string
  components: ComponentNode[]
}
export type UpdateDataModel = {
  surfaceId: string
  path?: string
  value?: unknown
}
export type DeleteSurface = { surfaceId: string }

export type SurfaceMessage =
  | { version?: "v0.9"; createSurface: CreateSurface }
  | { version?: "v0.9"; updateComponents: UpdateComponents }
  | { version?: "v0.9"; updateDataModel: UpdateDataModel }
  | { version?: "v0.9"; deleteSurface: DeleteSurface }

/** An action as the agent writes it on a component. */
export type ActionSpec = {
  event: { name: string; context?: Record<string, unknown> }
}

/** What the host receives when the person triggers an action. */
export type SurfaceAction = {
  name: string
  surfaceId: string
  sourceComponentId: string
  /** The action's context with every binding resolved to its current value. */
  context: Record<string, unknown>
  timestamp: string
}

/** A node the renderer couldn't draw, reported so the agent can fix it. */
export type SurfaceIssue = {
  surfaceId: string
  componentId: string
  code: "UNKNOWN_COMPONENT" | "VALIDATION_FAILED" | "LIMIT_EXCEEDED"
  message: string
}

export type SurfaceState = {
  id: string
  catalogId: string
  components: Record<string, ComponentNode>
  data: unknown
}

import * as React from "react"

import type { SurfaceMessage, SurfaceState } from "@/components/surface/types"

// Surface state: apply A2UI messages, read values by JSON Pointer.
//
//   const store = createSurfaceStore()
//   store.process(messages)                 // as they arrive (stream them)
//   const surface = useSurface(store, "spend")
//
// Inside a chat reply you usually have the whole (or partial, streaming)
// message list in a tool part: `surfaceFromMessages(part.input.messages)`.

/* ---------------------------- JSON Pointer ---------------------------- */

function tokens(pointer: string): string[] {
  if (pointer === "" || pointer === "/") return []
  return pointer
    .replace(/^\//, "")
    .split("/")
    .map((t) => t.replace(/~1/g, "/").replace(/~0/g, "~"))
}

/** Join a relative path ("name") onto a base ("/models/2"). Absolute paths win. */
export function joinPath(base: string | undefined, path: string): string {
  if (path.startsWith("/") || !base)
    return path.startsWith("/") ? path : `/${path}`
  return `${base.replace(/\/$/, "")}/${path}`
}

export function getAt(data: unknown, pointer: string): unknown {
  let cur: unknown = data
  for (const t of tokens(pointer)) {
    if (cur == null || typeof cur !== "object") return undefined
    cur = (cur as Record<string, unknown>)[t]
  }
  return cur
}

/** Immutable set; `value === undefined` deletes the key. */
export function setAt(data: unknown, pointer: string, value: unknown): unknown {
  const ts = tokens(pointer)
  if (ts.length === 0) return value
  const [head, ...rest] = ts
  const base: Record<string, unknown> | unknown[] = Array.isArray(data)
    ? [...data]
    : data && typeof data === "object"
      ? { ...(data as Record<string, unknown>) }
      : /^\d+$/.test(head)
        ? []
        : {}
  const next = rest.length
    ? setAt(
        (base as Record<string, unknown>)[head],
        `/${rest.join("/")}`,
        value
      )
    : value
  if (next === undefined && !rest.length) {
    if (Array.isArray(base)) base.splice(Number(head), 1)
    else delete (base as Record<string, unknown>)[head]
  } else {
    ;(base as Record<string, unknown>)[head] = next
  }
  return base
}

/* ------------------------------- reduce ------------------------------- */

export function applyMessage(
  surfaces: Map<string, SurfaceState>,
  message: SurfaceMessage
) {
  if ("createSurface" in message && message.createSurface) {
    const { surfaceId, catalogId } = message.createSurface
    const prev = surfaces.get(surfaceId)
    surfaces.set(surfaceId, {
      id: surfaceId,
      catalogId,
      components: prev?.components ?? {},
      data: prev?.data ?? {},
    })
  } else if ("updateComponents" in message && message.updateComponents) {
    const { surfaceId, components } = message.updateComponents
    const prev = surfaces.get(surfaceId) ?? {
      id: surfaceId,
      catalogId: "",
      components: {},
      data: {},
    }
    const next = { ...prev.components }
    for (const c of components ?? [])
      if (c && typeof c.id === "string" && typeof c.component === "string")
        next[c.id] = c
    surfaces.set(surfaceId, { ...prev, components: next })
  } else if ("updateDataModel" in message && message.updateDataModel) {
    const { surfaceId, path = "/", value } = message.updateDataModel
    const prev = surfaces.get(surfaceId) ?? {
      id: surfaceId,
      catalogId: "",
      components: {},
      data: {},
    }
    surfaces.set(surfaceId, { ...prev, data: setAt(prev.data, path, value) })
  } else if ("deleteSurface" in message && message.deleteSurface) {
    surfaces.delete(message.deleteSurface.surfaceId)
  }
}

/** Build surfaces from a message list (whole or partial, e.g. a streaming tool input). */
export function surfacesFromMessages(messages: readonly unknown[] | undefined) {
  const surfaces = new Map<string, SurfaceState>()
  for (const m of messages ?? [])
    if (m && typeof m === "object") applyMessage(surfaces, m as SurfaceMessage)
  return surfaces
}

/** The first (usually only) surface in a message list. */
export function surfaceFromMessages(
  messages: readonly unknown[] | undefined
): SurfaceState | undefined {
  return surfacesFromMessages(messages).values().next().value
}

/* -------------------------------- store ------------------------------- */

export type SurfaceStore = ReturnType<typeof createSurfaceStore>

export function createSurfaceStore(initial?: readonly SurfaceMessage[]) {
  let surfaces = surfacesFromMessages(initial)
  const listeners = new Set<() => void>()
  const emit = () => listeners.forEach((l) => l())
  return {
    process(messages: SurfaceMessage | readonly SurfaceMessage[]) {
      const next = new Map(surfaces)
      for (const m of Array.isArray(messages) ? messages : [messages])
        applyMessage(next, m as SurfaceMessage)
      surfaces = next
      emit()
    },
    /** Two-way bindings (inputs) write here. */
    setData(surfaceId: string, path: string, value: unknown) {
      const s = surfaces.get(surfaceId)
      if (!s) return
      const next = new Map(surfaces)
      next.set(surfaceId, { ...s, data: setAt(s.data, path, value) })
      surfaces = next
      emit()
    },
    get: (id: string) => surfaces.get(id),
    all: () => surfaces,
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
  }
}

export function useSurface(store: SurfaceStore, surfaceId: string) {
  return React.useSyncExternalStore(store.subscribe, () => store.get(surfaceId))
}

// Numbers are formatted by the renderer, never by the agent: a component
// takes the raw value and a `format`, the surface supplies locale and
// currency. "1287.4" + "currency" → "$1,287" (en-US) or "R$ 1.287" (pt-BR).

export type ValueFormat =
  | "number"
  | "integer"
  | "currency"
  | "percent"
  | "compact"
  | "duration"
  | "date"
  | "text"

export type FormatOptions = { locale?: string; currency?: string }

export function formatValue(
  value: unknown,
  format: ValueFormat = "text",
  { locale = "en-US", currency = "USD" }: FormatOptions = {}
): string {
  if (value == null) return ""
  if (format === "text" || (typeof value === "string" && format !== "date"))
    return String(value)
  if (format === "date") {
    const d = new Date(value as string | number)
    return Number.isNaN(d.getTime())
      ? String(value)
      : d.toLocaleDateString(locale, { month: "short", day: "numeric" })
  }
  const n = Number(value)
  if (!Number.isFinite(n)) return String(value)
  switch (format) {
    case "integer":
      return Math.round(n).toLocaleString(locale)
    case "currency":
      return n.toLocaleString(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: Math.abs(n) < 100 ? 2 : 0,
      })
    case "percent":
      return n.toLocaleString(locale, {
        style: "percent",
        maximumFractionDigits: 1,
      })
    case "compact":
      return n.toLocaleString(locale, {
        notation: "compact",
        maximumFractionDigits: 1,
      })
    case "duration": {
      if (n < 60) return `${Math.round(n)} s`
      if (n < 3600) return `${Math.round(n / 60)} min`
      return `${(n / 3600).toFixed(1)} h`
    }
    default:
      return n.toLocaleString(locale, { maximumFractionDigits: 2 })
  }
}

import type * as React from "react"
import { z } from "zod"

import type { ActionSpec } from "@/components/surface/types"
import type { FormatOptions } from "@/components/surface/format"

// A catalog is the vocabulary an agent may compose a surface from. Each
// entry is a Zod schema of its props (as the component receives them, after
// bindings resolve) plus a render function built on uia pieces. The same
// schema validates what the agent sent, describes the entry to the agent
// (`catalogToJSONSchema`, `catalogToPrompt`) and types the implementation.
//
//   const Stat = defineComponent({
//     name: "Stat",
//     description: "One number that answers the question, with its label.",
//     props: z.object({ label: z.string(), value: z.number(), format: format.optional() }),
//     render: (p, ctx) => <Stat …/>,
//   })
//   export const catalog = defineCatalog("https://uia.dev/catalog/v1", [Stat, …])
//
// Agents never send classes, colours or code: only names from the catalog,
// enums (`tone`, `format`, `columns`) and data. Taste lives in the renderer.

/* --------------------------- shared schemas --------------------------- */

/** Children: a list of ids, or a template repeated over a bound array. */
export const children = z
  .union([
    z.array(z.string()),
    z
      .object({ path: z.string(), componentId: z.string() })
      .describe(
        "Repeat componentId once per item of the array at path; inside it, relative paths read the item."
      ),
  ])
  .describe("Ids of child components, or a template over a data array.")

export const action = z
  .object({
    event: z.object({
      name: z
        .string()
        .describe("Named event the agent handles, e.g. raise_limit."),
      context: z
        .record(z.string(), z.unknown())
        .optional()
        .describe(
          "Values sent with the event; bindings ({path}) resolve at click time."
        ),
    }),
  })
  .describe(
    "What happens when the person triggers it: a named event back to the agent."
  )

export const tone = z.enum([
  "neutral",
  "success",
  "warning",
  "destructive",
  "attention",
  "info",
])
export const format = z
  .enum([
    "number",
    "integer",
    "currency",
    "percent",
    "compact",
    "duration",
    "date",
    "text",
  ])
  .describe(
    "How the renderer formats the raw value (locale and currency come from the host)."
  )

/** Props every node may carry; handled by the renderer, not the entry. */
const common = z.object({
  id: z.string(),
  component: z.string(),
  span: z
    .number()
    .int()
    .min(1)
    .max(4)
    .optional()
    .describe("Columns to span inside a Grid."),
})

/* ------------------------------ entries ------------------------------- */

export type RenderContext = {
  surfaceId: string
  componentId: string
  /** Render a child by id (a skeleton while it hasn't streamed in). */
  child: (id: string | undefined) => React.ReactNode
  /** Render `children` (ids or a template). */
  children: (ref: unknown) => React.ReactNode[]
  /** A click handler for an action spec, or undefined when there is none. */
  action: (spec: ActionSpec | undefined) => (() => void) | undefined
  /** For two-way bindings: the data path a prop was bound to, if any. */
  boundPath: (prop: string) => string | undefined
  /** Write a bound value (inputs). */
  set: (path: string, value: unknown) => void
  format: (value: unknown, f?: z.infer<typeof format>) => string
  formatOptions: FormatOptions
  size: "default" | "sm"
}

export type CatalogEntry<P = Record<string, unknown>> = {
  name: string
  description: string
  /** Higher-level entries the agent should prefer when the intent matches. */
  kind: "layout" | "display" | "data" | "input" | "block"
  props: z.ZodType<P>
  render: (props: P, ctx: RenderContext) => React.ReactNode
  /** Example for the prompt: one component node. */
  example?: Record<string, unknown>
}

export function defineComponent<S extends z.ZodObject>(entry: {
  name: string
  description: string
  kind: CatalogEntry["kind"]
  props: S
  render: (props: z.infer<S>, ctx: RenderContext) => React.ReactNode
  example?: Record<string, unknown>
}): CatalogEntry {
  return entry as unknown as CatalogEntry
}

export type Catalog = {
  id: string
  components: Record<string, CatalogEntry>
}

export function defineCatalog(id: string, entries: CatalogEntry[]): Catalog {
  return { id, components: Object.fromEntries(entries.map((e) => [e.name, e])) }
}

/** Extend a catalog with your own entries (or replace some of its own). */
export function extendCatalog(
  base: Catalog,
  entries: CatalogEntry[],
  id = base.id
): Catalog {
  return {
    id,
    components: {
      ...base.components,
      ...Object.fromEntries(entries.map((e) => [e.name, e])),
    },
  }
}

/* ---------------------------- for the agent --------------------------- */

const RESERVED = new Set([
  "id",
  "component",
  "children",
  "child",
  "action",
  "span",
])
const pathRef = {
  type: "object",
  properties: { path: { type: "string" } },
  required: ["path"],
  additionalProperties: false,
}

/**
 * JSON Schema of the catalog, published at its id. Every data prop also
 * accepts a binding (`{ "path": "/x" }`).
 */
export function catalogToJSONSchema(catalog: Catalog) {
  const components: Record<string, unknown> = {}
  for (const [name, e] of Object.entries(catalog.components)) {
    const schema = z.toJSONSchema(
      common.extend((e.props as z.ZodObject).shape),
      { io: "input", unrepresentable: "any" }
    ) as {
      properties?: Record<string, unknown>
      [k: string]: unknown
    }
    for (const [k, v] of Object.entries(schema.properties ?? {})) {
      if (!RESERVED.has(k)) schema.properties![k] = { anyOf: [v, pathRef] }
    }
    schema.properties!.component = { const: name }
    components[name] = { description: e.description, kind: e.kind, ...schema }
  }
  return { $id: catalog.id, version: "v0.9", components }
}

/** A compact description for a system prompt or tool description. */
export function catalogToPrompt(catalog: Catalog) {
  const order = ["block", "layout", "data", "display", "input"] as const
  const lines = [
    `Compose UI as A2UI v0.9 messages with catalogId "${catalog.id}".`,
    'Components are a flat list with ids; children reference ids; the root component has id "root".',
    'Props take a literal or a binding {"path":"/pointer"} into the data model (updateDataModel).',
    'Actions are {"event":{"name","context"}}. Never send classes, colours or code; format numbers with `format`, not by hand.',
    "Prefer a block when it matches the intent; otherwise compose from layout + data components.",
    "",
  ]
  for (const kind of order) {
    const entries = Object.values(catalog.components).filter(
      (e) => e.kind === kind
    )
    if (!entries.length) continue
    lines.push(`${kind.toUpperCase()}`)
    for (const e of entries) {
      const keys = Object.keys((e.props as z.ZodObject).shape).join(", ")
      lines.push(`- ${e.name}(${keys}): ${e.description}`)
    }
  }
  return lines.join("\n")
}

import * as React from "react"

import { cn } from "@/lib/utils"
import { Skeleton } from "@/components/ui/skeleton"
import type { Catalog, RenderContext } from "@/components/surface/catalog"
import {
  formatValue,
  type FormatOptions,
  type ValueFormat,
} from "@/components/surface/format"
import { getAt, joinPath, setAt } from "@/components/surface/store"
import type {
  ActionSpec,
  ComponentNode,
  SurfaceAction,
  SurfaceIssue,
  SurfaceState,
} from "@/components/surface/types"

// <Surface>: draws an A2UI surface with a catalog. The same renderer works
// for a full page (a dashboard assembled for this moment) and inside a chat
// reply (`size="sm"`).
//
//   <Surface surface={surface} catalog={uiaCatalog} onAction={send} />
//
// - Streams well: a child that hasn't arrived yet is a skeleton; nothing
//   renders until "root" exists.
// - Validates each node with its catalog schema. A node that fails, or whose
//   component isn't in the catalog, is dropped (or, with `showIssues`, shown
//   as a quiet placeholder) and reported through `onIssue` so the agent can
//   fix and resend. The rest of the surface still renders.
// - Inputs write to a local copy of the data model (`onDataChange` to keep
//   your own); actions resolve their context bindings, then call `onAction`.

const MAX_NODES = 400
const MAX_DEPTH = 16

function isPathRef(v: unknown): v is { path: string } {
  return (
    !!v &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    Object.keys(v).length === 1 &&
    typeof (v as { path?: unknown }).path === "string"
  )
}

function resolveDeep(
  value: unknown,
  data: unknown,
  scope: string | undefined
): unknown {
  if (isPathRef(value)) return getAt(data, joinPath(scope, value.path))
  if (Array.isArray(value)) return value.map((v) => resolveDeep(v, data, scope))
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, resolveDeep(v, data, scope)])
    )
  }
  return value
}

const PASS_THROUGH = new Set(["children", "child", "action"])
const COMMON = new Set(["id", "component", "span", "fallback"])

function rawProps(
  node: ComponentNode,
  data: unknown,
  scope: string | undefined
) {
  const raw: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(node))
    if (!COMMON.has(k))
      raw[k] = PASS_THROUGH.has(k) ? v : resolveDeep(v, data, scope)
  return raw
}

function issueText(error: {
  issues: { path: PropertyKey[]; message: string }[]
}) {
  return error.issues
    .map((i) => `${i.path.map(String).join(".") || "(props)"}: ${i.message}`)
    .join("; ")
}

/** Walk what's reachable from root and list what can't render, for the agent. */
function collectIssues(
  surface: SurfaceState,
  catalog: Catalog,
  data: unknown
): SurfaceIssue[] {
  const out: SurfaceIssue[] = []
  const seen = new Set<string>()
  let count = 0
  const add = (
    componentId: string,
    code: SurfaceIssue["code"],
    message: string
  ) => out.push({ surfaceId: surface.id, componentId, code, message })
  const visit = (id: string | undefined, depth: number, scope?: string) => {
    if (!id) return
    const node = surface.components[id]
    if (!node) return // still streaming
    const key = `${id}@${scope ?? ""}`
    if (seen.has(key)) return
    seen.add(key)
    if (++count > MAX_NODES || depth > MAX_DEPTH)
      return add(
        id,
        "LIMIT_EXCEEDED",
        `Max ${MAX_NODES} nodes and depth ${MAX_DEPTH}.`
      )
    const entry = catalog.components[node.component]
    if (!entry) {
      add(
        id,
        "UNKNOWN_COMPONENT",
        `"${node.component}" is not in catalog ${catalog.id}.`
      )
      return visit(
        typeof node.fallback === "string" ? node.fallback : undefined,
        depth + 1,
        scope
      )
    }
    const parsed = entry.props.safeParse(rawProps(node, data, scope))
    if (!parsed.success) add(id, "VALIDATION_FAILED", issueText(parsed.error))
    const kids = node.children
    if (Array.isArray(kids))
      kids.forEach((c) => visit(String(c), depth + 1, scope))
    else if (
      kids &&
      typeof kids === "object" &&
      "componentId" in kids &&
      "path" in kids
    ) {
      const base = joinPath(scope, String((kids as { path: string }).path))
      const items = getAt(data, base)
      if (Array.isArray(items) && items.length)
        visit(
          String((kids as { componentId: string }).componentId),
          depth + 1,
          `${base}/0`
        )
    }
    for (const k of ["child", "aside"])
      if (typeof node[k] === "string")
        visit(node[k] as string, depth + 1, scope)
    if (Array.isArray(node.tabs))
      for (const t of node.tabs as { child?: string }[])
        visit(t?.child, depth + 1, scope)
  }
  visit("root", 0)
  return out
}

export function Surface({
  surface,
  catalog,
  size = "default",
  locale,
  currency,
  showIssues = false,
  onAction,
  onIssue,
  onDataChange,
  className,
}: {
  surface: SurfaceState | undefined
  catalog: Catalog
  size?: "default" | "sm"
  locale?: string
  currency?: string
  /** Show a placeholder where a node failed (dev, playgrounds). */
  showIssues?: boolean
  onAction?: (action: SurfaceAction) => void
  onIssue?: (issue: SurfaceIssue) => void
  onDataChange?: (path: string, value: unknown, data: unknown) => void
  className?: string
}) {
  const [overrides, setOverrides] = React.useState<Record<string, unknown>>({})
  const data = React.useMemo(() => {
    let d = surface?.data
    for (const [p, v] of Object.entries(overrides)) d = setAt(d, p, v)
    return d
  }, [surface?.data, overrides])

  // Issues come from a pure pass over the tree (same checks as rendering),
  // reported once each after commit.
  const issues = React.useMemo(
    () => (surface ? collectIssues(surface, catalog, data) : []),
    [surface, catalog, data]
  )
  const reported = React.useRef(new Set<string>())
  React.useEffect(() => {
    for (const issue of issues) {
      const key = `${issue.componentId}:${issue.code}:${issue.message}`
      if (reported.current.has(key)) continue
      reported.current.add(key)
      onIssue?.(issue)
    }
  }, [issues, onIssue])

  if (!surface || !surface.components.root) {
    return (
      <Skeleton
        data-slot="surface-pending"
        className={cn("h-24 w-full rounded-2xl", className)}
      />
    )
  }

  const formatOptions: FormatOptions = { locale, currency }
  let count = 0

  const placeholder = (componentId: string, text: string) =>
    showIssues ? (
      <div
        key={componentId}
        data-slot="surface-issue"
        className="rounded-xl border border-dashed border-border px-3 py-2 eyebrow text-faint-foreground"
      >
        {text}
      </div>
    ) : null

  const renderNode = (
    id: string | undefined,
    depth: number,
    scope?: string
  ): React.ReactNode => {
    if (!id) return null
    const node: ComponentNode | undefined = surface.components[id]
    // Not streamed in yet.
    if (!node)
      return (
        <Skeleton
          key={`${id}-${scope ?? ""}`}
          className="h-12 w-full rounded-xl"
        />
      )
    if (++count > MAX_NODES || depth > MAX_DEPTH) return null
    const entry = catalog.components[node.component]
    if (!entry) {
      const fallback =
        typeof node.fallback === "string" ? node.fallback : undefined
      return fallback
        ? renderNode(fallback, depth + 1, scope)
        : placeholder(id, `Unsupported · ${node.component}`)
    }

    const parsed = entry.props.safeParse(rawProps(node, data, scope))
    if (!parsed.success)
      return placeholder(id, `${node.component} · ${issueText(parsed.error)}`)

    const ctx: RenderContext = {
      surfaceId: surface.id,
      componentId: id,
      size,
      formatOptions,
      format: (v, f) => formatValue(v, f as ValueFormat, formatOptions),
      child: (childId) => renderNode(childId, depth + 1, scope),
      children: (ref) => {
        if (Array.isArray(ref))
          return ref.map((c) => (
            <React.Fragment key={String(c)}>
              {renderNode(String(c), depth + 1, scope)}
            </React.Fragment>
          ))
        if (
          ref &&
          typeof ref === "object" &&
          "path" in ref &&
          "componentId" in ref
        ) {
          const { path, componentId } = ref as {
            path: string
            componentId: string
          }
          const base = joinPath(scope, path)
          const items = getAt(data, base)
          if (!Array.isArray(items)) return []
          return items.map((_, i) => (
            <React.Fragment key={`${componentId}-${i}`}>
              {renderNode(componentId, depth + 1, `${base}/${i}`)}
            </React.Fragment>
          ))
        }
        return []
      },
      action: (spec: ActionSpec | undefined) => {
        if (!spec?.event?.name) return undefined
        return () =>
          onAction?.({
            name: spec.event.name,
            surfaceId: surface.id,
            sourceComponentId: id,
            context: (resolveDeep(spec.event.context ?? {}, data, scope) ??
              {}) as Record<string, unknown>,
            timestamp: new Date().toISOString(),
          })
      },
      boundPath: (prop) => {
        const v = node[prop]
        return isPathRef(v) ? joinPath(scope, v.path) : undefined
      },
      set: (path, value) => {
        setOverrides((o) => ({ ...o, [path]: value }))
        onDataChange?.(path, value, setAt(data, path, value))
      },
    }

    const rendered = entry.render(parsed.data as Record<string, unknown>, ctx)
    const span = typeof node.span === "number" ? node.span : undefined
    return span ? (
      <div
        key={id}
        className="min-w-0 @xl:col-span-(--span)"
        style={{ "--span": span } as React.CSSProperties}
      >
        {rendered}
      </div>
    ) : (
      <React.Fragment key={id}>{rendered}</React.Fragment>
    )
  }

  return (
    <div
      data-slot="surface"
      data-surface={surface.id}
      className={cn("@container flex min-w-0 flex-col", className)}
    >
      {renderNode("root", 0)}
    </div>
  )
}
